@Component("insuranceProduct-handler")
@ProcessingGroup("insuranceProduct-processing-group")
public class InsuranceProductEventHandler {
	
	// core constructor
	InsuranceProductEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateInsuranceProductEvent
     */
    @EventHandler
    public void handle( CreateInsuranceProductEvent event) {
        entityManager.persist(new InsuranceProduct(event.getInsuranceProductId(), event.getName(), event.getProductCode(), event.getInsurer(), event.getCoverageDefinitions(), event.getLineOfBusiness()));
    }

    /*
     * @param	event UpdateInsuranceProductEvent
     */
    @EventHandler
    public InsuranceProduct handle( UpdateInsuranceProductEvent event) {
    	entityManager.merge(new InsuranceProduct(event.getInsuranceProductId(), event.getName(), event.getProductCode(), event.getInsurer(), event.getCoverageDefinitions(), event.getLineOfBusiness()));
    }
    
    /*
     * @param	event DeleteInsuranceProductEvent
     */
    @EventHandler
    public void on( DeleteInsuranceProductEvent event) {
    	InsuranceProduct entity = new InsuranceProduct();
   
    	// ------------------------------------------
    	// apply the InsuranceProductId
    	// ------------------------------------------
    	entity.setInsuranceProductId( event.getInsuranceProductId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final InsuranceProductRepository insuranceProductEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(InsuranceProductEventHandler.class.getName());

}
